head.b:skin:
/* ==========================================================================
   Blogger Theme Skin: راہِ دینِ اسلام (Rah-e-Deen-Islam)
   Colors: Emerald Green (#064E3B), Gold (#D4AF37), Warm Ivory (#FCFBF7)
   ========================================================================== */

:root {
  --emerald-950: #011c15;
  --emerald-900: #022c22;
  --emerald-800: #064e3b;
  --emerald-700: #047857;
  --emerald-50:  #ecfdf5;
  --gold-600:    #aa771c;
  --gold-500:    #d4af37;
  --gold-400:    #e5c158;
  --gold-50:     #fdfcf7;
  --ivory-100:   #fcfbf7;
  --ivory-200:   #f7f4ec;
  --ivory-300:   #efe9dc;
  --text-dark:   #1a2421;
  --text-muted:  #4b5e56;
  --font-urdu:   'Noto Nastaliq Urdu', 'Jameel Noori Nastaliq', serif;
  --font-arabic: 'Amiri', 'Traditional Arabic', serif;
  --font-ui:     'Plus Jakarta Sans', system-ui, sans-serif;
}

body {
  direction: rtl;
  text-align: right;
  font-family: var(--font-urdu);
  font-size: 1.05rem;
  line-height: 2.1;
  color: var(--text-dark);
  background-color: var(--ivory-100);
  margin: 0;
  padding: 0;
}

/* Top Bar */
.blogger-top-bar {
  background: var(--emerald-950);
  color: var(--ivory-200);
  padding: 8px 24px;
  border-bottom: 1px solid rgba(212, 175, 55, 0.3);
  font-size: 0.88rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
}

/* Header */
.blogger-header {
  background: linear-gradient(135deg, var(--emerald-900) 0%, var(--emerald-800) 100%);
  color: #fff;
  border-bottom: 3px solid var(--gold-500);
  padding: 16px 24px;
  box-shadow: 0 4px 16px rgba(0,0,0,0.15);
}

.header-flex {
  max-width: 1250px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
}

.site-title h1 {
  font-family: var(--font-urdu);
  font-size: 2rem;
  color: var(--gold-400);
  margin: 0;
  line-height: 1.3;
}

.site-title p {
  font-family: var(--font-ui);
  font-size: 0.8rem;
  letter-spacing: 2px;
  color: var(--ivory-200);
  margin: 0;
}

/* Navigation */
.blogger-nav {
  background: var(--emerald-950);
  border-bottom: 1px solid rgba(212, 175, 55, 0.3);
}

.nav-container {
  max-width: 1250px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  overflow-x: auto;
  padding: 4px 16px;
}

.nav-menu-item {
  color: var(--ivory-100);
  text-decoration: none;
  padding: 10px 16px;
  font-size: 0.95rem;
  white-space: nowrap;
  border-bottom: 2px solid transparent;
  transition: all 0.2s ease;
}

.nav-menu-item:hover, .nav-menu-item.active {
  color: var(--gold-300);
  border-bottom-color: var(--gold-500);
  background: rgba(212, 175, 55, 0.1);
}

/* Main Layout */
.blogger-layout {
  max-width: 1250px;
  margin: 32px auto;
  padding: 0 20px;
  display: grid;
  grid-template-columns: 2.8fr 1.2fr;
  gap: 32px;
}

@media (max-width: 900px) {
  .blogger-layout {
    grid-template-columns: 1fr;
  }
}

/* Post Cards */
.post {
  background: #ffffff;
  border: 1px solid var(--ivory-300);
  border-radius: 14px;
  padding: 24px;
  margin-bottom: 28px;
  box-shadow: 0 4px 12px rgba(2, 44, 34, 0.05);
}

.post-title {
  font-size: 1.55rem;
  color: var(--emerald-900);
  margin-top: 0;
  margin-bottom: 10px;
}

.post-title a {
  color: inherit;
  text-decoration: none;
}

.post-title a:hover {
  color: var(--gold-600);
}

.post-meta {
  font-size: 0.85rem;
  color: var(--text-muted);
  border-bottom: 1px dashed rgba(212, 175, 55, 0.4);
  padding-bottom: 8px;
  margin-bottom: 16px;
}

.post-body {
  line-height: 2.2;
  color: var(--text-dark);
}

/* Sidebar Widgets */
.sidebar-box {
  background: #ffffff;
  border: 1.5px solid rgba(212, 175, 55, 0.35);
  border-radius: 14px;
  padding: 20px;
  margin-bottom: 24px;
}

.sidebar-title {
  font-size: 1.25rem;
  color: var(--emerald-900);
  border-bottom: 2px solid var(--gold-500);
  padding-bottom: 8px;
  margin-bottom: 14px;
}

/* Buttons */
.btn-gold {
  display: inline-block;
  background: linear-gradient(135deg, var(--gold-400) 0%, var(--gold-500) 100%);
  color: var(--emerald-950);
  padding: 8px 18px;
  border-radius: 8px;
  text-decoration: none;
  font-weight: 700;
}

/* Footer */
.blogger-footer {
  background: var(--emerald-950);
  color: var(--ivory-200);
  border-top: 3px solid var(--gold-500);
  padding: 36px 20px;
  text-align: center;
  margin-top: 40px;
}
